package vn.cinema.security;
import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.oauth2.jwt.Jwt;import vn.cinema.exception.Problem;
public class Actor{public static long id(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!(a.getPrincipal() instanceof Jwt j))throw new Problem(401,"Vui lòng đăng nhập");return ((Number)j.getClaim("userId")).longValue();}public static boolean admin(){var a=SecurityContextHolder.getContext().getAuthentication();return a!=null&&a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));}public static void requireAdmin(){if(!admin())throw new Problem(403,"Chỉ quản trị viên được thực hiện");}public static void owner(long id){if(!admin()&&id()!=id)throw new Problem(403,"Bạn không có quyền xem dữ liệu này");}}